export interface TeamSection {
  key: "leadership" | "astrology" | "technology" | "marketing";
  heading: Localized;
  intro: Localized;
  /** Members shown as full profile cards. */
  members: string[];
  /** Members already profiled elsewhere on the page: a short pointer only. */
  alsoSee: { member: string; note: Localized }[];
}

